import { type ClassValue, clsx } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

// tw-merge only knows stock sizes and misreads these as text COLOR group, so size and color in one cn() collide and one is dropped.
const textScale = [
  "micro",
  "caption",
  "label",
  "body",
  "body-lg",
  "heading-1",
  "heading-2",
  "heading-3",
  "heading-4",
  // legacy aliases kept until their call sites migrate to canonical rungs above
  "meta",
  "title-sm",
  "title-md",
  "title-lg",
  "display",
];

// unregistered, tw-merge reads these as shadow COLOR and lets them ride alongside later box-shadow util, so skin's override loses by CSS order instead of argument order
const shadowScale = ["pop", "soft", "modal"];

const twMerge = extendTailwindMerge({
  extend: {
    classGroups: {
      "font-size": [{ text: textScale }],
      shadow: [{ shadow: shadowScale }],
    },
  },
  // stock Tailwind bakes line-height into `text-*`, so twMerge lets font-size clear preceding `leading-*`; this scale is size-only, so that conflict must go
  override: {
    conflictingClassGroups: {
      "font-size": [],
    },
  },
});

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

import type { ReactNode } from "react";
import type { SelectionIndicator } from "@/components/control-ui/control-props";
import type { ControlTone, ControlVariant } from "@/components/control-ui/control-variants";
// Missing module = no skin installed yet; any skin pack creates it: npx shadcn add <registry>/r/skin-<id>.json
import { skin } from "./skin.config";

type StatelessPart = Record<never, never>;
export type SkinAdornmentContexts = {
  button: { layer: { variant: ControlVariant; tone: ControlTone } };
  "chat-layout": { titlebar: StatelessPart };
  "chat-thought": { details: StatelessPart };
  dialog: { titlebar: StatelessPart };
  "chat-composer": { "send-layer": { sendCount: number } };
};

export type SkinAdornmentScope = keyof SkinAdornmentContexts;
export type SkinAdornmentPart<Scope extends SkinAdornmentScope> = keyof SkinAdornmentContexts[Scope];

type AdornmentEntry<Ctx> = ReactNode | ((ctx: Ctx) => ReactNode);

export type ControlUiSkin = {
  /** Scopes theme.css/skin.css via data-skin; components stamp it on portal containers. */
  id: string;
  /** Stamps data-motion="reduced", collapsing --duration-* to 0ms. Never `animation:none` — ripple cleanup still needs `animationend` to fire. */
  motion?: "reduced";
  /** Locks skin to one scheme; page's .dark class must then follow it, since Shiki, native color-scheme, and dark: utilities key off .dark, not skin tokens. Undefined = adaptive, both blocks authored. */
  colorScheme?: "light" | "dark";
  /** Geometry, not slot restyle — padding, gap, rounding, and shadow across sidebar gap/container/inner. explicit `variant` prop wins; undefined keeps "sidebar". */
  sidebarLayout?: SidebarLayout;
  /** App-wide choice: sidebars and trees all glide or none do. Explicit `indicator` still wins; undefined also skips highlight engine's lazy chunk. */
  indicators?: { sidebar?: SelectionIndicator; tree?: SelectionIndicator };
  /** Any CSS length. Seeds --sidebar-width; caller's own value still wins. Undefined keeps shadcn's 16rem. */
  sidebarWidth?: string;
  /** effects.css keys off data-effects ancestor attribute. top-shine is CSS-only; ripple needs runtime's document pointer listener. */
  effects?: ControlEffect[];
  adornments?: {
    [Scope in SkinAdornmentScope]?: {
      [Part in SkinAdornmentPart<Scope>]?: AdornmentEntry<SkinAdornmentContexts[Scope][Part]>;
    };
  };
};

export type SidebarLayout = "sidebar" | "floating" | "inset";

export type ControlEffect = "top-shine" | "ripple" | "hover-circle";

export type ControlEffectValue = ControlEffect | ControlEffect[];

export function controlEffectsAttribute(effects?: ControlEffectValue): string | undefined {
  if (!effects) return undefined;
  const value = (Array.isArray(effects) ? effects : [effects]).join(" ");
  return value.length > 0 ? value : undefined;
}

/** Read at render time so getter-based configs stay live. Portals stamp it on their positioner, which lands outside any token-scoped ancestor. */
export function activeSkin(): ControlUiSkin {
  return skin;
}

export function skinId(): string {
  return skin.id;
}

/** Sidebar falls back: variant prop → this → "sidebar". */
export function skinSidebarLayout(): SidebarLayout | undefined {
  return skin.sidebarLayout;
}

/** Component falls back: indicator prop → this → "none". */
export function skinIndicator(component: "sidebar" | "tree"): SelectionIndicator | undefined {
  return skin.indicators?.[component];
}

/** SidebarProvider seeds --sidebar-width from this; caller-provided value still wins. */
export function skinSidebarWidth(): string | undefined {
  return skin.sidebarWidth;
}

/** Portals stamp result next to data-skin; ControlEffectsRuntime mirrors it on <html>. */
export function skinEffects(): string | undefined {
  return controlEffectsAttribute(skin.effects);
}

function resolveAdornment<Ctx>(entry: AdornmentEntry<Ctx> | undefined, ctx: Ctx): ReactNode | undefined {
  if (entry === undefined) return undefined;
  return typeof entry === "function" ? entry(ctx) : entry;
}

export function skinAdornment<Scope extends SkinAdornmentScope, Part extends SkinAdornmentPart<Scope>>(
  scope: Scope,
  part: Part,
  ctx: SkinAdornmentContexts[Scope][Part],
): ReactNode | undefined {
  return resolveAdornment(skin.adornments?.[scope]?.[part], ctx);
}

export function hasSkinAdornment<Scope extends SkinAdornmentScope, Part extends SkinAdornmentPart<Scope>>(
  scope: Scope,
  part: Part,
): boolean {
  return skin.adornments?.[scope]?.[part] !== undefined;
}

import type { ComponentProps, ReactElement } from "react";

// Tracks the consumer's React types: form onSubmit is FormEvent-based before React 19.2 and SubmitEvent-based after.
export type FormSubmitEvent = Parameters<NonNullable<ComponentProps<"form">["onSubmit"]>>[0];

export type ControlledChoice<TValue extends string = string> = {
  value?: TValue;
  defaultValue?: NoInfer<TValue>;
  onValueChange?: (value: TValue) => void;
};

export type ControlledMultiChoice<TValue extends string = string> = {
  value?: TValue[];
  defaultValue?: NoInfer<TValue>[];
  onValueChange?: (value: TValue[]) => void;
};

export type RenderProp<Props, State extends Record<string, unknown> = Record<string, unknown>> =
  | ReactElement
  | ((props: Props, state: State) => ReactElement<unknown>);

export type OpenChangeReason =
  | "trigger-hover"
  | "trigger-focus"
  | "trigger-press"
  | "outside-press"
  | "escape-key"
  | "close-watcher"
  | "close-press"
  | "focus-out"
  | "list-navigation"
  | "item-press"
  | "sibling-open"
  | "cancel-open"
  | "input-change"
  | "input-clear"
  | "input-press"
  | "clear-press"
  | "chip-remove-press"
  | "imperative-action"
  | "swipe"
  | "none";

export type OpenChangeEventDetails = {
  reason: OpenChangeReason;
  event: Event;
  cancel: () => void;
  allowPropagation: () => void;
  isCanceled: boolean;
  isPropagationAllowed: boolean;
  trigger: Element | undefined;
};

export type SelectionIndicator = "none" | "slide";

// Read server-side (RSC layouts) and written client-side; lives here because ui/sidebar.tsx is "use client".
export const SIDEBAR_COOKIE_NAME = "sidebar_state";

import { cva } from "class-variance-authority";

export type ControlSize = "xs" | "sm" | "md" | "lg";

export const controlSize = cva("", {
  variants: {
    size: {
      xs: "h-[var(--control-h-xs)] gap-1 px-[calc(var(--padding-x)*0.6)] text-caption",
      sm: "h-[var(--control-h-sm)] gap-1.5 px-[calc(var(--padding-x)*0.75)] text-label",
      md: "h-[var(--control-h-md)] gap-1.5 px-[var(--padding-x)] text-body",
      lg: "h-[var(--control-h-lg)] gap-2 px-[calc(var(--padding-x)*1.25)] text-body",
    },
  },
  defaultVariants: {
    size: "md",
  },
});

/** Re-points the size gap at the button knob, which a skin can re-value; the raw utility sits in a layer no skin rule can outrank. */
export const buttonGapClass = "gap-[var(--cui-button-gap)]";

export const controlVariants = ["solid", "surface", "ghost", "quiet"] as const;

export type ControlVariant = (typeof controlVariants)[number];

export const controlTones = ["neutral", "primary", "danger"] as const;

export type ControlTone = (typeof controlTones)[number];

#!/usr/bin/env node
import { existsSync, readdirSync, readFileSync, statSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

// Read-only audit of the wiring the registry cannot see from inside one install:
// the CSS entry, the app's own token blocks fighting the skin, and the data-skin stamp.
const controlUiDir = path.dirname(path.dirname(fileURLToPath(import.meta.url)));
const themeSuffix = ".control-ui-theme.css";

function findAppDir(start) {
  let directory = start;
  while (!existsSync(path.join(directory, "components.json"))) {
    const parent = path.dirname(directory);
    if (parent === directory) throw new Error(`No components.json found above ${start}`);
    directory = parent;
  }
  return directory;
}

const appDir = findAppDir(controlUiDir);
const componentsConfig = JSON.parse(readFileSync(path.join(appDir, "components.json"), "utf8"));
const entryRelative = componentsConfig.tailwind?.css;
if (typeof entryRelative !== "string") throw new Error(`components.json in ${appDir} names no tailwind.css entry`);
const entryPath = path.join(appDir, entryRelative);

const stripComments = (css) => css.replaceAll(/\/\*[\s\S]*?\*\//g, " ");

// One nesting-aware pass: top-level blocks of a stylesheet (or of a block body).
function parseBlocks(css) {
  const blocks = [];
  let depth = 0;
  let preludeStart = 0;
  let bodyStart = 0;
  for (let index = 0; index < css.length; index += 1) {
    const character = css[index];
    if (character === "{") {
      if (depth === 0) bodyStart = index + 1;
      depth += 1;
    } else if (character === "}") {
      depth -= 1;
      if (depth === 0) {
        blocks.push({ prelude: css.slice(preludeStart, bodyStart - 1).trim(), body: css.slice(bodyStart, index) });
        preludeStart = index + 1;
      }
    } else if (character === ";" && depth === 0) {
      preludeStart = index + 1;
    }
  }
  return blocks;
}

// @layer/@media/@supports wrap real blocks one level down; selector and @theme blocks hold declarations.
function flattenBlocks(css) {
  return parseBlocks(css).flatMap((block) => (/^@(layer|media|supports)\b/.test(block.prelude) ? flattenBlocks(block.body) : [block]));
}

function declarations(body) {
  const properties = new Map();
  let depth = 0;
  for (const statement of body.split(";")) {
    const open = (statement.match(/{/g) ?? []).length;
    const close = (statement.match(/}/g) ?? []).length;
    if (depth === 0) {
      const match = /^\s*(--[\w-]+)\s*:\s*([\s\S]*)$/.exec(statement);
      if (match) properties.set(match[1], match[2].trim());
    }
    depth += open - close;
  }
  return properties;
}

function tokenNames(filePath, preludeTest) {
  if (!existsSync(filePath)) return new Set();
  const names = new Set();
  for (const block of flattenBlocks(stripComments(readFileSync(filePath, "utf8")))) {
    if (preludeTest(block.prelude)) for (const name of declarations(block.body).keys()) names.add(name);
  }
  return names;
}

const isThemeBlock = (prelude) => /^@theme\b/.test(prelude);
const isSkinScope = (prelude) => prelude.includes("[data-skin");
const ownedThemeKeys = tokenNames(path.join(controlUiDir, "styles/theme.css"), isThemeBlock);
const skinTokens = new Set([
  ...tokenNames(path.join(controlUiDir, "styles/skin-theme.css"), isSkinScope),
  ...tokenNames(path.join(controlUiDir, "styles/theme.css"), isSkinScope),
]);

const skinIds = new Set(
  [...stripComments(readFileSync(path.join(controlUiDir, "styles/skin-theme.css"), "utf8")).matchAll(/\[data-skin="([\w-]+)"\]/g)].map(
    (match) => match[1],
  ),
);

const errors = [];
const warnings = [];

// App-owned stylesheets: the entry plus every relative import that lands outside the control-ui directory.
const appStylesheets = [];
const visited = new Set();
const pending = [entryPath];
while (pending.length > 0) {
  const filePath = pending.pop();
  if (visited.has(filePath) || !existsSync(filePath)) continue;
  visited.add(filePath);
  const css = stripComments(readFileSync(filePath, "utf8"));
  appStylesheets.push({ filePath, css });
  for (const [, specifier] of css.matchAll(/@import\s+"(\.[^"]+)"/g)) {
    const resolved = path.resolve(path.dirname(filePath), specifier);
    if (!existsSync(resolved)) {
      errors.push(`${path.relative(appDir, filePath)} imports "${specifier}" which resolves to no file — run scripts/fix-css-imports.mjs`);
    } else if (!resolved.startsWith(controlUiDir + path.sep) && !specifier.endsWith(themeSuffix)) {
      pending.push(resolved);
    }
  }
}

const entryImports = [...stripComments(readFileSync(entryPath, "utf8")).matchAll(/@import\s+"([^"]+)"/g)].map((match) => match[1]);
const lastNonTheme = entryImports.reduce((last, specifier, index) => (specifier.endsWith(themeSuffix) ? last : index), -1);
const firstTheme = entryImports.findIndex((specifier) => specifier.endsWith(themeSuffix));
if (firstTheme !== -1 && firstTheme < lastNonTheme) {
  errors.push(`${entryRelative}: the ${themeSuffix} import must stay last — run scripts/fix-css-imports.mjs`);
}

for (const { filePath, css } of appStylesheets) {
  const relative = path.relative(appDir, filePath);
  for (const block of flattenBlocks(css)) {
    const declared = declarations(block.body);
    if (isThemeBlock(block.prelude)) {
      const conflicting = [...declared].filter(
        ([name, value]) => (ownedThemeKeys.has(name) || skinTokens.has(name)) && value !== `var(${name})`,
      );
      if (conflicting.length > 0) {
        errors.push(
          `${relative}: ${block.prelude} redeclares Control UI keys — Tailwind merges @theme blocks and the later value wins, ` +
            `silently rewiring these utilities away from the skin: ${conflicting.map(([name]) => name).join(", ")}`,
        );
      }
    } else if (/(^|,)\s*(:root|html|body|\.dark)\s*($|,)/.test(block.prelude)) {
      const dead = [...declared.keys()].filter((name) => skinTokens.has(name));
      const live = [...declared.keys()].filter((name) => !skinTokens.has(name));
      if (dead.length > 0) {
        warnings.push(
          live.length > 0
            ? `${relative}: "${block.prelude}" is hybrid — ${dead.length} declaration(s) are dead (out-specified by the skin scope: ` +
                `${dead.join(", ")}) while ${live.join(", ")} still paint a second palette next to the skin`
            : `${relative}: "${block.prelude}" only redeclares skin tokens (${dead.join(", ")}) — dead under the skin scope, delete it`,
        );
      }
    }
  }
}

const skipDirectories = new Set(["node_modules", ".git", "dist", "build", "out", ".next", ".turbo", "coverage"]);
const stampExtensions = new Set([".html", ".tsx", ".jsx", ".ts", ".js", ".mjs", ".astro", ".vue", ".svelte", ".mdx"]);

function findStamps(directory) {
  return readdirSync(directory).flatMap((entry) => {
    const filePath = path.join(directory, entry);
    if (statSync(filePath).isDirectory()) {
      return skipDirectories.has(entry) || filePath === controlUiDir ? [] : findStamps(filePath);
    }
    if (!stampExtensions.has(path.extname(entry))) return [];
    const source = readFileSync(filePath, "utf8");
    return [...source.matchAll(/data-skin=\{?["']([\w-]+)["']/g)]
      .map((match) => ({ filePath, id: match[1] }))
      .concat(/dataset\.skin|setAttribute\(\s*["']data-skin["']/.test(source) ? [{ filePath, id: null }] : []);
  });
}

const stamps = findStamps(appDir);
if (stamps.length === 0) {
  errors.push(
    `No data-skin stamp found in ${appDir} — without data-skin="${[...skinIds][0] ?? "<skin id>"}" on the root element, ` +
      "every token is undeclared and portalled surfaces render unstyled",
  );
} else if (!stamps.some((stamp) => stamp.id === null || skinIds.has(stamp.id))) {
  const found = [...new Set(stamps.map((stamp) => stamp.id))].join(", ");
  errors.push(`data-skin stamp(s) found (${found}) but the installed skin declares ${[...skinIds].join(", ")} — the ids must match`);
}

for (const warning of warnings) console.warn(`warn  ${warning}`);
for (const error of errors) console.error(`error ${error}`);
if (errors.length === 0 && warnings.length === 0) console.log("control-ui doctor: clean.");
process.exit(errors.length > 0 ? 1 : 0);

#!/usr/bin/env node
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

// This file ships inside the installed control-ui directory, so its own location is the one path
// the registry cannot know: the real prefix every re-appended canonical import must fold onto.
const controlUiDir = path.dirname(path.dirname(fileURLToPath(import.meta.url)));
const marker = "components/control-ui/";
const importPattern = /^@import\s+"(\.[^"]+)";?$/;
const themeSuffix = ".control-ui-theme.css";

function findAppDir(start) {
  let directory = start;
  while (!existsSync(path.join(directory, "components.json"))) {
    const parent = path.dirname(directory);
    if (parent === directory) throw new Error(`No components.json found above ${start}`);
    directory = parent;
  }
  return directory;
}

const appDir = findAppDir(controlUiDir);
const componentsConfig = JSON.parse(readFileSync(path.join(appDir, "components.json"), "utf8"));
const entryRelative = componentsConfig.tailwind?.css;
if (typeof entryRelative !== "string") throw new Error(`components.json in ${appDir} names no tailwind.css entry`);
const entryPath = path.join(appDir, entryRelative);
const entryDir = path.dirname(entryPath);

const toPosix = (value) => value.split(path.sep).join("/");

function realSpecifier(tail) {
  const specifier = toPosix(path.relative(entryDir, path.join(controlUiDir, tail)));
  return specifier.startsWith(".") ? specifier : `./${specifier}`;
}

const original = readFileSync(entryPath, "utf8");
const seen = new Set();
const unresolved = [];
let folded = 0;

// A file saved without a trailing newline glues the next appended import onto the same line.
function splitGluedImports(line) {
  const statements = [...line.matchAll(/@import\s+"[^"]+";?/g)].map((match) => match[0]);
  const rest = line.replaceAll(/@import\s+"[^"]+";?/g, "").trim();
  if (statements.length < 2 || rest !== "") return [line];
  return statements;
}

const repairedLines = original
  .split("\n")
  .flatMap(splitGluedImports)
  .flatMap((line) => {
    const match = importPattern.exec(line.trim());
    if (!match) return [line];
    let specifier = match[1];
    if (!existsSync(path.resolve(entryDir, specifier))) {
      const markerIndex = specifier.lastIndexOf(marker);
      const candidate = markerIndex === -1 ? null : realSpecifier(specifier.slice(markerIndex + marker.length));
      if (candidate !== null && existsSync(path.resolve(entryDir, candidate))) {
        specifier = candidate;
        folded += 1;
      } else {
        unresolved.push(specifier);
      }
    }
    if (seen.has(specifier)) {
      folded += 1;
      return [];
    }
    seen.add(specifier);
    return [`@import "${specifier}";`];
  });

const isImportLine = (line) => importPattern.test(line.trim());
const isThemeImport = (line) => isImportLine(line) && line.includes(themeSuffix);
const themeImports = repairedLines.filter(isThemeImport);
const orderedLines = repairedLines.filter((line) => !isThemeImport(line));
if (themeImports.length > 0) {
  const lastImportIndex = orderedLines.reduce((last, line, index) => (isImportLine(line) ? index : last), -1);
  orderedLines.splice(lastImportIndex + 1, 0, ...themeImports);
}

const repaired = orderedLines.join("\n");
if (repaired !== original) {
  writeFileSync(entryPath, repaired);
  console.log(`Folded ${folded} re-appended import(s) in ${toPosix(path.relative(appDir, entryPath))}.`);
} else {
  console.log(`${toPosix(path.relative(appDir, entryPath))} is already in sync.`);
}
if (unresolved.length > 0) {
  console.error(`Imports resolving to no file:\n${unresolved.map((specifier) => `- ${specifier}`).join("\n")}`);
  process.exit(1);
}

/* Load alongside Tailwind v4 and at least one complete skin theme — nothing here paints without a pack's token values. */

@custom-variant dark (&:is(.dark *));

/* biome-ignore-start lint/complexity/noImportantStyles: Reduced motion must override skin and inline motion. */
/* Motion collapses under OS preference; !important wins over skin-scoped tokens and editor duration overrides. */
@media (prefers-reduced-motion: reduce) {
  :where(:root),
  [data-skin] {
    --duration-fast: 0ms !important;
    --duration-base: 0ms !important;
    --duration-slow: 0ms !important;
  }

  :where([data-skin], [data-skin] *, [data-skin]::before, [data-skin]::after, [data-skin] *::before, [data-skin] *::after) {
    scroll-behavior: auto !important;
    transition-delay: 0ms !important;
    transition-duration: 0ms !important;
    animation-delay: 0ms !important;
    animation-duration: 1ms !important;
    animation-iteration-count: 1 !important;
  }
}

/* Explicit motion kill-switch, same collapse as above but opt-in via attribute, not OS preference.
   Skin's `motion: "reduced"` flag or the theme editor toggle stamps [data-motion="reduced"] on <html>;
   also targets skin-scoped portals directly since their [data-skin] tokens would beat inherited root values. */
:root[data-motion="reduced"],
[data-motion="reduced"][data-skin],
[data-motion="reduced"] [data-skin] {
  --duration-fast: 0ms !important;
  --duration-base: 0ms !important;
  --duration-slow: 0ms !important;
}

:where(
  [data-motion="reduced"],
  [data-motion="reduced"] *,
  [data-motion="reduced"]::before,
  [data-motion="reduced"]::after,
  [data-motion="reduced"] *::before,
  [data-motion="reduced"] *::after
) {
  scroll-behavior: auto !important;
  transition-delay: 0ms !important;
  transition-duration: 0ms !important;
  animation-delay: 0ms !important;
  animation-duration: 1ms !important;
  animation-iteration-count: 1 !important;
}
/* biome-ignore-end lint/complexity/noImportantStyles: Reduced motion must override skin and inline motion. */

/* Skin-root defaults at zero specificity — any pack declaration (theme.css or skin.css) wins.
   First family: derived-tier contract tokens, re-valued by a pack only when it diverges.
   Second family: core mechanics (math constants + aliases) that live OFF the contract entirely. */
:where([data-skin]) {
  /* font roles default to the skin's face; re-value one to give headings their own. */
  --font-body: var(--font-sans);
  --font-display: var(--font-sans);

  /* majority defaults measured over the shipped packs; a pack declares one only to diverge,
     and the dark block below carries the mode-split ones */
  --primary-text: oklch(from var(--primary) 0.48 c h);
  --destructive-text: oklch(from var(--destructive) 0.48 c h);
  --ring-opacity: 1;
  --focus-ring: var(--ring);
  --focus-ring-width: 2px;
  --focus-ring-style: solid;
  --focus-ring-offset: 2px;

  --text-micro: 0.625rem;
  --text-caption: 0.6875rem;
  --text-body: 0.875rem;
  --text-body-lg: 1rem;
  --text-heading-4: 0.9375rem;
  --text-heading-4--line-height: 1.4;
  --text-heading-4--font-weight: 600;
  --text-heading-3: 1.125rem;
  --text-heading-3--line-height: 1.35;
  --text-heading-3--font-weight: 600;
  --text-heading-2: 1.375rem;
  --text-heading-2--line-height: 1.25;
  --text-heading-2--font-weight: 600;
  --text-heading-1: 1.875rem;
  --text-heading-1--line-height: 1.15;
  --text-heading-1--font-weight: 700;
  --text-heading-1--letter-spacing: -0.018em;
  --text-display: 2.25rem;
  --text-display--line-height: 1.1;
  --text-display--font-weight: 600;
  --text-display--letter-spacing: -0.026em;

  --corner-shape: round;
  --corner-radius-fit: 0.5;
  --radius-popover: calc(var(--radius-popup-item-fit) + clamp(0px, var(--radius-popup-item-fit) * 1000, var(--popover-padding) - 1px));

  --shadow-highlight: oklch(1 0 0 / 0.62);
